@dataclass
class BatchResumeState:
    checkpoint_id: str
    processed_hashes: set
    last_index: int
    batch_metadata: Dict[str, Any]
    pending_items: List[Any]
    completed: bool

class BatchResumer:
    def __init__(self, resume_dir: str = ".scanner_resume"):
        self.resume_dir = Path(resume_dir)
        self.resume_dir.mkdir(exist_ok=True, parents=True)
        self._lock_path = self.resume_dir / ".lock"

    @contextmanager
    def _atomic_write(self, path: Path, data: bytes):
        tmp = path.with_suffix(".tmp")
        tmp.write_bytes(data)
        tmp.rename(path)
        yield

    def _state_path(self, job_id: str) -> Path:
        safe_id = hashlib.sha256(job_id.encode()).hexdigest()[:16]
        return self.resume_dir / f"state_{safe_id}.pkl"

    def save_state(self, job_id: str, state: BatchResumeState):
        with self._lock_path.open("w") as fl:
            fl.write(str(os.getpid()))
        path = self._state_path(job_id)
        with self._atomic_write(path, pickle.dumps(asdict(state), protocol=pickle.HIGHEST_PROTOCOL)):
            pass

    def load_state(self, job_id: str) -> Optional[BatchResumeState]:
        path = self._state_path(job_id)
        if not path.exists():
            return None
        with path.open("rb") as f:
            data = pickle.load(f)
            return BatchResumeState(**data)

    def resume_or_start(self, job_id: str, initial_metadata: Dict[str, Any]) -> Tuple[BatchResumeState, bool]:
        existing = self.load_state(job_id)
        if existing and not existing.completed:
            return existing, True  # resuming
        new_state = BatchResumeState(
            checkpoint_id=job_id,
            processed_hashes=set(),
            last_index=-1,
            batch_metadata=initial_metadata,
            pending_items=[],
            completed=False
        )
        return new_state, False  # fresh start

    def mark_completed(self, job_id: str):
        state = self.load_state(job_id)
        if state:
            state.completed = True
            self.save_state(job_id, state)

    def prune_old(self, keep_days: int = 7):
        import time
        now = time.time()
        for p in self.resume_dir.glob("state_*.pkl"):
            if (now - p.stat().st_mtime) > (keep_days * 86400):
                p.unlink()
