        if is_resume:
            print(f"[CRASH‑SAFE] Resuming job {job_id} from checkpoint {state.last_index + 1}")
            pending_queue = list(state.pending_items)
        else:
            pending_queue = list(self._collect_items(input_paths))
            state.pending_items = pending_queue.copy()
            state.processed_hashes.clear()
            state.last_index = -1
            resumer.save_state(job_id, state)

        # Atomic batch processor
        batch_size = kwargs.get('batch_size', 100)
