def main():
    parser = argparse.ArgumentParser(description="Crash‑safe LLM mapper")
    parser.add_argument("paths", nargs="+", help="Input files/directories")
    parser.add_argument("--resume-id", help="Explicit resume ID")
    parser.add_argument("--batch-size", type=int, default=100)
    parser.add_argument("--strict", action="store_true")
    parser.add_argument("--prune-checkpoints", action="store_true")

